  "ui.engine.035": { zh: "{name}只收不卖：市场不出售现货（可等玩家二手挂单，或自己制造）。", en: "{name} is bought but never sold: the market carries no stock (wait for a resale listing, or build it yourself)." },
  "ui.engine.036": { zh: "{name}当前没有现货：市场供应簿为空——用「挂买单」等 市场补给后自动成交，或过一会儿再来（常驻 20 分钟一轮补给）。", en: "{name} is out of stock: the supply book is empty — place a buy order and it fills automatically after the next restock, or come back later (standard goods restock every 20 minutes)." },
