  "ui.FitPage.141": { zh: "{base} ← 同类第 {p2} 件：只削剩余缺口（收益递减）", en: "{base} ← same kind #{p2}: trims the remaining gap only (diminishing returns)" },
  "ui.FitPage.142": { zh: "查看 / 套用 / 重命名 / 删除本船型的装配方案（最多 {FIT_PRESET_MAX} 套）；每套可展开「明细」看逐位装了什么", en: "View, apply, rename or delete fitting presets for this hull (up to {FIT_PRESET_MAX}); expand Details on any preset to see what is fitted slot by slot" },
  "ui.FitPage.143": { zh: "{droneBayTotal} m³ · 战斗只放飞下方清单中已装入的无人机", en: "{droneBayTotal} m³ · only the drones loaded into the list below launch in combat" },
  "ui.FitPage.144": { zh: "{p1}：每 {p2} 秒修甲 {p3} / 结构 {p4}", en: "{p1}: repairs {p3} armor / {p4} structure every {p2} seconds" },
  "ui.FitPage.145": { zh: "（加力推进点火期 {p1} m/s；{p2}）", en: "(afterburner burn {p1} m/s; {p2})" },
  "ui.FitPage.146": { zh: "（装备 +{p1}%）", en: " (modules +{p1}%)" },
  "ui.FitPage.147": { zh: " · 跨星系航行耗时 ×{p1}（含航行技能）", en: " · cross-system travel time ×{p1} (navigation skills included)" },
  "ui.FitPage.148": { zh: "槽位布局：{p1} 高 / {p2} 中 / {p3} 低（复数安装）；抗性按递减方式合成（上限 90%）；多装与「动力」细则见手册速览「装配」。命中率 = 本船炮台 / 导弹架 / 激光炮的整机均值（船体加成加算、索敌件与推进失稳只压掷命中武器；激光必中计 100%），不含敌方回避与距离衰减；超过 100% 的部分是余量，实战里用于抵消射程削减与敌舰回避。", en: "Slot layout: {p1} high / {p2} mid / {p3} low (multiple fittings allowed); resistances combine with diminishing returns (cap 90%); see the handbook quick reference under Fitting for stacking and power details. Accuracy = the average across this ship's turrets, missile launchers and lasers (hull bonuses add on; targeting modules and thruster instability only weigh on weapons that roll to hit; lasers always hit and count as 100%), before enemy evasion and range falloff; anything above 100% is margin, which combat spends against range cuts and enemy evasion." },
  "ui.FitPage.149": { zh: "第 {p1} 位（空）——点击选择装备", en: "Slot {p1} (empty) — click to choose a module" },
  "ui.FitPage.150": { zh: "第 {p1} 位 · 点击更换{p2}", en: "Slot {p1} · click to swap{p2}" },
  "ui.FitPage.151": { zh: "匹配 {p1} 件", en: "{p1} match(es)" },
  "ui.FitPage.152": { zh: "{p1} 件 · 按稀有度排序", en: "{p1} items · sorted by rarity" },
  "ui.FitPage.153": { zh: " · 弹伤 {p1}", en: " · damage per shot {p1}" },
  "ui.FitPage.154": { zh: "{baseName}：本船{baseName2}档（未设 = 基础弹；开战时同族取\"能装得最多\"的一档）", en: "{baseName}: this ship's {baseName2} tier (unset = basic ammo; in combat the tier of that family that holds the most is loaded)" },
  "ui.FitPage.155": { zh: "{p1}：单发更高（{p2} vs {p3}）；开战按档预载——同族里\"能装得最多\"的那一档会被实际装填，装不满也照装。仓库 ×{haveMk2}", en: "{p1}: higher damage per shot ({p2} vs {p3}); preloaded by tier when the fight starts — the tier of that family that holds the most is what gets loaded, even if it cannot fill up. Storage ×{haveMk2}" },
  "ui.FitPage.156": { zh: "无人机舱容量：已装 {p1} / {cap} m³（船体 + 甲板扩展）；清单 CPU 占用 {droneCpu}（计入预算）", en: "Drone bay capacity: {p1} / {cap} m³ loaded (hull + deck expansion); the list uses {droneCpu} CPU (counted against the budget)" },
  "ui.FitPage.157": { zh: "舱内清单：战斗只放飞已装入的；仓库中其余无人机不出战", en: "Bay list: only what is loaded launches in combat; the rest of your drones stay in storage" },
  "ui.FitPage.158": { zh: "{id}：无人机舱清单（战斗只放飞已装入的；仓库中其余无人机不出战）", en: "{id}: drone bay list (only what is loaded launches in combat; the rest stay in storage)" },
  "ui.FitPage.159": { zh: "{p1}（单架 {p2} m³ · CPU {p3}；仓库 ×{have}）", en: "{p1} ({p2} m³ each · CPU {p3}; storage ×{have})" },
