  "ui.Industry.049": { zh: "理论收益率：", en: "Theoretical return:" },
  "ui.Industry.050": { zh: "（余料不足「加开一条线」，缺口见按钮提示）", en: " (not enough material left to open another line; the button tooltip shows the shortfall)" },
  "ui.Industry.051": { zh: "当前价格与技能下制造不如直接卖材料。", en: "At current prices and skills, manufacturing pays less than selling the materials." },
  "ui.Industry.052": { zh: "卖出给空间站按收购档（约 6~7 折），自用装配则按现货价计。", en: "Selling to the station follows the buy tier (about 60–70%), while modules you fit yourself are valued at stock price." },
  "ui.Industry.053": { zh: "（净亏：直接卖材料更划算）", en: " (net loss: selling the materials pays better)" },
  "ui.Industry.054": { zh: "（净 · 现货价）", en: " (net · stock price)" },
