  "ui.Industry.056": { zh: "打开后", en: "After opening" },
  "ui.Industry.057": { zh: "循环制造", en: "Repeat manufacturing" },
  "ui.Industry.058": { zh: "目标", en: "Target" },
  "ui.Industry.059": { zh: "目标批数：本卡全部制造线合计做到这么多批就停（留空 = 直到材料不足自动停）；一批的产出件数见蓝图说明；回车、点空白处、或离开本页都会记住", en: "Target batches: every line on this card stops once they add up to this many (blank means keep going until materials run out); the units per batch are in the blueprint description; pressing Enter, clicking away or leaving the page all remember it" },
  "ui.Industry.060": { zh: "（全卡合计）", en: " (card total)" },
  "ui.Industry.061": { zh: "已产", en: "Produced" },
  "ui.Industry.062": { zh: "已停线：", en: "Line stopped:" },
  "ui.Industry.063": { zh: "作用于本卡全部制造线", en: "Applies to every production line on this card" },
  "ui.Industry.064": { zh: "入舰船仓库", en: "To Ship Storage" },
  "ui.Industry.065": { zh: "入库", en: "To storage" },
  "ui.Industry.066": { zh: "（旧作业：老规则免占用线，跑完即止）", en: " (legacy job: a line from the old rules that holds no core and ends when it finishes)" },
  "ui.Industry.067": { zh: "⚙ 旧作业", en: "⚙ Legacy job" },
  "ui.Industry.068": { zh: "⛏ 主控亲自", en: "⛏ Manual by you" },
  "ui.Industry.069": { zh: "取消这条制造线：材料按材料学折扣后的实际用量全额退回（AI 核心自动归还），其它线不受影响", en: "Cancel this production line: materials come back in full at the discounted amount actually consumed (the AI core returns automatically), and other lines are unaffected" },
  "ui.Industry.070": { zh: "■ 取消", en: "■ Cancel" },
  "ui.Industry.071": { zh: "手动制造", en: "Manual manufacturing" },
  "ui.Industry.072": { zh: "选择接入 AI 核心：一枚核心驱动一条线（驱动期间该核心被占用并计入 AI 核心启用上限——上限由 AI 核心上限技能决定，与 AI 副船任务共用）", en: "Choose an AI core to attach: one core drives one line (while driving it the core is occupied and counts against the AI core limit — the limit comes from the AI core skill and is shared with AI auxiliary tasks)" },
  "ui.Industry.073": { zh: "AI 制造", en: "AI manufacturing" },
  "ui.Industry.074": { zh: "学习该配方（书架已有书）", en: "Learn this recipe (the book is on the shelf)" },
  "ui.Industry.075": { zh: "虫洞专属图纸：市场不出售（只收不卖）——点此跳到「扫描虫洞」进洞，在遗迹与图纸货柜里打捞同名图纸", en: "Wormhole-only blueprint: never sold on the market (it buys but does not sell) — click to jump to Scan wormhole, head inside and salvage the same blueprint from ruins and blueprint containers" },
  "ui.Industry.076": { zh: "去虫洞（遗迹打捞）", en: "To the wormhole (ruins salvage)" },
  "ui.Industry.077": { zh: "✕ 虫洞未解锁", en: "✕ Wormhole not unlocked" },
  "ui.Industry.078": { zh: "本门一次性图纸的名额已用尽：要再造需要再获得一张同名图纸——点此跳市场看这张图纸的订单（稀有订单层 / 奇货偶有现货）", en: "The one-use blueprint allowance for this recipe is used up: building again needs another copy — click to jump to its orders on the market (rare order tier; Enigma stock shows up now and then)" },
  "ui.Industry.079": { zh: "一次性图纸：不能学习，只能用一次——组装机开工时消耗。点此跳市场看这张图纸的订单（稀有订单层 / 奇货偶有现货）", en: "One-use blueprint: cannot be learned and works only once — it is consumed when the assembler starts. Click to jump to this blueprint's orders on the market (rare order tier; Enigma stock shows up now and then)" },
  "ui.Industry.080": { zh: "市场求购蓝图书", en: "Buy blueprint book on the market" },
  "ui.Industry.081": { zh: "（名额已用尽）", en: " (allowance used up)" },
  "ui.Industry.082": { zh: "本门一次性图纸的名额已用尽：这张不在市场流通，只能从稀有残骸的额外战利品里再得到一张同名图纸", en: "The one-use blueprint allowance for this recipe is used up: this one never reaches the market, so another copy has to come from the extra loot of rare wrecks" },
  "ui.Industry.083": { zh: "一次性图纸：不能学习，只能用一次。这张不在市场流通——只能从稀有残骸的额外战利品里得到", en: "One-use blueprint: cannot be learned and works only once. This one never reaches the market — it only comes from the extra loot of rare wrecks" },
  "ui.Industry.084": { zh: "✕ 制造名额已用尽（稀有残骸）", en: "✕ Manufacturing allowance used up (rare wreck)" },
  "ui.Industry.085": { zh: "✕ 需要一次性图纸（稀有残骸）", en: "✕ Needs a one-use blueprint (rare wreck)" },
  "ui.Industry.086": { zh: "跳到市场的该蓝图行情详情：买现货或按自己的价挂买单", en: "Jump to this blueprint's market details: buy stock or place a buy order at your own price" },
  "ui.Industry.087": { zh: "这张图纸不在市场流通目录——来源见产物说明（洞内打捞 / 稀有残骸的额外战利品等）", en: "This blueprint is not in the market catalog — see the product description for where it comes from (wormhole salvage, extra loot from rare wrecks, and so on)" },
  "ui.Industry.088": { zh: "✕ 无市场渠道", en: "✕ No market channel" },
  "ui.Industry.089": { zh: "仓库＋机库", en: "Storage + hangar" },
  "ui.Industry.090": { zh: "已学会的配方才能开工；你亲自开限 1 条、其余每条由一枚 AI 核心驱动（同一蓝图可多条、不同蓝图并行）。", en: "Only learned recipes can start jobs; you can run one line by hand, and every other line needs its own AI core (several lines of the same blueprint are fine, and different blueprints run in parallel)." },
  "ui.Industry.091": { zh: "制造线", en: "Production line" },
  "ui.Industry.092": { zh: "条 · 装备", en: "lines · modules" },
  "ui.Industry.093": { zh: "该筛选下暂无蓝图——换个分类、或把「全部子类 / 全部图纸」点回来看看。", en: "No blueprints under this filter — pick another category, or switch back to All subcategories / All blueprints." },
  "ui.Industry.094": { zh: "这一类书架里没有书，也没有可逆向的碎片。", en: "No books or redeemable fragments in this category on the shelf." },
