  "ui.IndustryPage.010": { zh: "你不在空间站（母港或已建成副站）——先返航停靠。", en: "You are not at a station (home port or a completed outpost) — return and dock first." },
  "ui.IndustryPage.011": { zh: "采矿作业中：先停止开采。", en: "Mining in progress: stop mining first." },
  "ui.IndustryPage.012": { zh: "打捞作业中：先停止打捞（或等满仓自动返航）。", en: "Salvage in progress: stop salvaging first (or wait for a full hold to bring the ship home)." },
  "ui.IndustryPage.013": { zh: "远征中：先召回或等待结束。", en: "On an expedition: recall the ship or wait for it to end." },
  "ui.IndustryPage.014": { zh: "掩护巡逻进行中：先召回。", en: "Escort patrol in progress: recall it first." },
  "ui.IndustryPage.015": { zh: "返航途中：到站后再运转。", en: "Returning home: run it after docking." },
  "ui.IndustryPage.016": { zh: "本卡的炉子已把料预占进炉内料账（货仓/仓库不再显示这批料）：等它拆完，或停炉把余料退回后再开新炉", en: "This card's unit has already reserved its feedstock in the unit ledger (that stock no longer shows in the hold or storage): wait for it to finish, or stop the unit to return the leftovers before opening a new one" },
  "ui.IndustryPage.017": { zh: "仓库/货仓里还没有原料：先采集（或从船货仓卸下），到市场购买也行", en: "No feedstock in storage or the hold yet: mine it first (or unload it from a ship's hold); buying on the market works too" },
  "ui.IndustryPage.018": { zh: "你已亲自运转着一台炉：先停它才能再亲自开一台（AI 核心不受此限）。", en: "You are already running a unit by hand: stop it before opening another by hand (AI cores are not limited by this)." },
  "ui.IndustryPage.019": { zh: "你已亲自开着一条制造线：先取消或等它完成才能亲自开炉（AI 核心不受此限）。", en: "You are already running a production line yourself: cancel it or wait for it to finish before opening a unit by hand (AI cores are not limited by this)." },
  "ui.IndustryPage.020": { zh: "由你亲自运转", en: "Run by you" },
  "ui.IndustryPage.021": { zh: "♨ 保底原材料：", en: "♨ Guaranteed materials:" },
  "ui.IndustryPage.022": { zh: "×约", en: "×~" },
  "ui.IndustryPage.023": { zh: "信用点/批（仓库", en: "credits/batch (storage" },
  "ui.IndustryPage.024": { zh: "按残骸来源危险度池的保底原材料估算（手动炉基准；AI 核心驱动时周期更长）——参考值，实际所得以回收拆解结算为准", en: "Estimated from the guaranteed materials of the source wreck's danger pool (manual unit baseline; AI-core operation takes longer) — a reference figure, since the salvage breakdown settles the actual payout" },
  "ui.IndustryPage.025": { zh: "保底 ≈", en: "Guaranteed ≈" },
  "ui.IndustryPage.026": { zh: "信用点/h", en: "credits/h" },
  "ui.IndustryPage.027": { zh: "♨ 产出：（当前无产出）", en: "♨ Output: (nothing yet)" },
