  "ui.IndustryPage.029": { zh: "（仓库", en: " (storage" },
  "ui.IndustryPage.030": { zh: "当前产出倍率下精炼不如直接卖原料。", en: "At the current output multiplier, refining pays less than selling the raw material." },
  "ui.IndustryPage.031": { zh: "数值已扣除耗料成本。", en: "Figures are already net of feedstock cost." },
  "ui.IndustryPage.032": { zh: "（净亏：直接卖原料更划算）", en: " (net loss: selling the raw material pays better)" },
  "ui.IndustryPage.033": { zh: "（净）", en: " (net)" },
  "ui.IndustryPage.034": { zh: "稀有残骸：解体时保底原材料之外必给一件——该敌群专属装备或特色装备，另附一批高阶原材料", en: "Rare wreck: breaking it up always yields one piece beyond the guaranteed materials — a dedicated or signature module of that hostile group, plus a batch of high-tier materials" },
  "ui.IndustryPage.035": { zh: "稀有", en: "Rare" },
  "ui.IndustryPage.036": { zh: "前往星图「残骸打捞」定位该残骸的来源星系（打捞后残骸带回站内回收拆解）", en: "Find the wreck's source system on the star map under Wreck Salvage (salvaged wrecks are brought back to the station for recycling and breakdown)" },
  "ui.IndustryPage.037": { zh: "去打捞", en: "Go salvage" },
  "ui.IndustryPage.038": { zh: "去矿带", en: "To the belts" },
  "ui.IndustryPage.039": { zh: "每批拆解 = 保底原材料 + 概率特色掉落；每烧满一个回收单元必给一件：专属装备或特色装备 + 高阶原材料", en: "Each breakdown = guaranteed materials + a chance at signature loot; every full recycling unit yields one guaranteed piece: a dedicated or signature module plus high-tier materials" },
  "ui.IndustryPage.040": { zh: "每批拆解 = 保底原材料 + 概率特色掉落", en: "Each breakdown = guaranteed materials + a chance at signature loot" },
  "ui.IndustryPage.041": { zh: "⛏ 主控", en: "⛏ Manual" },
  "ui.IndustryPage.042": { zh: "每批到点实时扣料", en: "Consumes feedstock each batch as it runs" },
  "ui.IndustryPage.043": { zh: "停这台炉：已完成批保留；本炉未用完的预占料退回物品仓库（AI 核心自动归还）", en: "Stop this unit: finished batches are kept and unused reserved feedstock returns to the warehouse (the AI core comes back automatically)" },
  "ui.IndustryPage.044": { zh: "停这台炉：已完成批保留；原料未锁定无需退回（AI 核心自动归还）", en: "Stop this unit: finished batches are kept and unlocked feedstock needs no refund (the AI core comes back automatically)" },
  "ui.IndustryPage.045": { zh: "每件到点实时扣掉一只货柜", en: "Consumes one container per item when the timer fires" },
  "ui.IndustryPage.046": { zh: "由你亲自运转一台：循环拆解，每批到点实时扣料（期间不可离港作业）", en: "You run one yourself: continuous breakdown, feedstock consumed each batch (you cannot undock for other work meanwhile)" },
  "ui.IndustryPage.047": { zh: "由你亲自运转一台：循环精炼，每批到点实时扣料（期间不可离港作业）", en: "You run one yourself: continuous refining, feedstock consumed each batch (you cannot undock for other work meanwhile)" },
  "ui.IndustryPage.048": { zh: "手动拆解", en: "Manual breakdown" },
  "ui.IndustryPage.049": { zh: "手动回收", en: "Manual salvage" },
  "ui.IndustryPage.050": { zh: "手动运转", en: "Manual run" },
  "ui.IndustryPage.051": { zh: "无可用 AI 核心：核心库为空或全部已在占用中——去市场购入「基础 AI 核心」（空间站直购），或先取消占用中的任务、训练「AI 核心操作学」/「工业自动化」扩容", en: "No AI core available: the core library is empty or every core is busy — buy a Basic AI Core on the market (direct from a station), cancel a running task, or train AI Core Operation / Industrial Automation to expand capacity" },
  "ui.IndustryPage.052": { zh: "选择接入 AI 核心：一枚核心驱动一台炉（驱动期间该核心被占用并计入 AI 核心启用上限——上限由 AI 核心上限技能决定，与 AI 副船任务共用）", en: "Choose an AI core to attach: one core drives one unit (while driving it the core is occupied and counts against the AI core limit — the limit comes from the AI core skill and is shared with AI auxiliary tasks)" },
  "ui.IndustryPage.053": { zh: "接入一枚闲置 AI 核心加开一台", en: "Attach an idle AI core to open another unit" },
  "ui.IndustryPage.054": { zh: "接入 AI 核心自动运转（不占副船与主控）", en: "Attach an AI core to run it automatically (uses no auxiliary ship and no manual slot)" },
  "ui.IndustryPage.055": { zh: "无可用 AI 核心：先去市场购入「基础 AI 核心」，或等占用中的核心归还", en: "No AI core available: buy a Basic AI Core on the market, or wait for an occupied core to come back" },
  "ui.IndustryPage.056": { zh: "AI 拆解", en: "AI breakdown" },
