  "ui.IndustryPage.060": { zh: "蓝图书架", en: "Blueprint Shelf" },
  "ui.IndustryPage.061": { zh: "产出倍率 = 基础 120% + 精炼学 +6%/级 + 高级回收处理 +3%/级（上限 165%）；残骸回收按保底原材料另算", en: "Output multiplier = base 120% + Refining +6%/level + Reprocessing +3%/level (cap 165%); wreck salvage is figured from guaranteed materials instead" },
  "ui.IndustryPage.062": { zh: "产出倍率", en: "Output multiplier" },
