  "ui.ItemsPage.019": { zh: "当前筛选下仓库里没有东西——换个分类，或点「全部」看全表。", en: "Nothing in the warehouse under this filter — pick another category, or hit All to see everything." },
  "ui.ItemsPage.020": { zh: "前往市场查看该装备的订单（价格/挂单/买入）", en: "Open this module's orders on the market (price / listings / buy)" },
