  "ui.ItemsPage.040": { zh: "船上没有足够空间（模块按 1 m³/件 计入货舱）。", en: "Not enough space aboard (modules take 1 m³ per unit in the hold)." },
  "ui.ItemsPage.041": { zh: "已装船 {p1}×{p2}（按 1 m³/件 计入货舱；装配请先卸回装备库）。", en: "Loaded {p1}×{p2} aboard (1 m³ per unit against the hold; to fit it, unload it to Module Storage first)." },
  "ui.ItemsPage.042": { zh: "已按市价售出 {p1} 单位，入账 {p2} 信用点。", en: "Sold {p1} units at market price for {p2} credits." },
