  "ui.MapPage.067": { zh: "估算 = 当前打捞器装配 × 当前密度 × 打捞/回收技能（参考值，实际所得以回收拆解结算为准）", en: "Estimate = current salvager fitting × current density × salvage and recycling skills (a reference figure, since the salvage breakdown settles the actual payout)" },
  "ui.MapPage.068": { zh: "停止打捞", en: "Stop salvaging" },
  "ui.MapPage.069": { zh: "已有打捞作业进行中（其它星系）——先停止或等满仓自动返航", en: "Salvage already running in another system — stop it first, or wait for a full hold to bring the ship home" },
  "ui.MapPage.070": { zh: "开始打捞（需高槽打捞器；默认自动循环，满舱返航卸货后自动续捞）", en: "Start salvaging (needs a salvager in a high slot; it loops by default, flying home to unload when full and then resuming)" },
